export const getProjectFileDestroyUrl = (project: number,
    params: ProjectFileDestroyParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/projects/${project}/file?${stringifiedParams}` : `/projects/${project}/file`
}

